-    forkPushTokenUrl: forkPushTokenUrl
+    forkPushTokenUrl: forkPushTokenUrl,
+    isWorkflowsPermissionRejection: isWorkflowsPermissionRejection,
+    workflowWriteParkLine: workflowWriteParkLine,
+    workflowWriteParkMarked: workflowWriteParkMarked
 };

