+    /refusing to allow a GitHub App to create or update workflow/i;
+var WORKFLOWS_OAUTH_REJECTION_RE =
+    /refusing to allow an OAuth App to create or update workflow [^\n]*without [`'\u0060]workflow[`'\u0060] scope/i;
