    // stderr tail (the fa PR #1591 streak class).
    try {
        var trail = silentUpdateFailureTrail(reason);
        var attempt = trail.attempt;
        if (trail.left > 0) {
            console.warn('  ⚠️  ' + key + ' fork silent-update push failure #' +
                attempt + ' recorded on the PR — ' + trail.left +
